<script setup lang="ts" generic="T extends Record<string, unknown>">
import {computed,ref} from 'vue'
import {ChevronDown,ChevronUp} from 'lucide-vue-next'
import {useHysRootAttrs} from '../../config'
export interface HysTableColumn {key:string;label:string;width?:string|number;align?:'left'|'center'|'right';sortable?:boolean}
const props=withDefaults(defineProps<{columns:HysTableColumn[];rows:T[];rowKey?:string;emptyText?:string;loading?:boolean;striped?:boolean;bordered?:boolean;size?:'sm'|'md'|'lg';caption?:string;rowClassName?:(row:T,index:number)=>string}>(),{rowKey:'id',size:'md'})
const emit=defineEmits<{rowClick:[row:T];sortChange:[sort:{key:string;direction:'asc'|'desc'}|null]}>(),hysRootAttrs=useHysRootAttrs(),sort=ref<{key:string;direction:'asc'|'desc'}|null>(null)
const sorted=computed(()=>!sort.value?props.rows:[...props.rows].sort((a,b)=>String(a[sort.value!.key]??'').localeCompare(String(b[sort.value!.key]??''),'zh-CN',{numeric:true})*(sort.value!.direction==='asc'?1:-1)))
function toggle(column:HysTableColumn){if(!column.sortable)return;sort.value=sort.value?.key!==column.key?{key:column.key,direction:'asc'}:sort.value.direction==='asc'?{key:column.key,direction:'desc'}:null;emit('sortChange',sort.value)}
</script>
<template><div v-bind="hysRootAttrs" class="hys-ui-table-scroll" :class="[{'hys-ui-table-striped':striped,'hys-ui-table-bordered':bordered},'hys-ui-table-'+size]" :aria-busy="loading"><table class="hys-ui-data-table"><caption v-if="caption">{{caption}}</caption><thead><tr><th v-for="column in columns" :key="column.key" scope="col" :aria-sort="column.sortable?(sort?.key===column.key?(sort.direction==='asc'?'ascending':'descending'):'none'):undefined" :style="{width:typeof column.width==='number'?column.width+'px':column.width,textAlign:column.align}"><button v-if="column.sortable" type="button" class="hys-ui-table-sort" @click="toggle(column)">{{column.label}}<component :is="sort?.key===column.key&&sort.direction==='desc'?ChevronDown:ChevronUp" :size="13"/></button><template v-else>{{column.label}}</template></th></tr></thead><tbody><tr v-if="loading"><td :colspan="columns.length"><slot name="loading">加载中…</slot></td></tr><template v-else><tr v-for="(row,index) in sorted" :key="String(row[rowKey]??index)" :class="rowClassName?.(row,index)" @click="emit('rowClick',row)"><td v-for="column in columns" :key="column.key" :style="{textAlign:column.align}"><slot :name="column.key" :row="row" :value="row[column.key]" :index="index">{{row[column.key]}}</slot></td></tr><tr v-if="!rows.length"><td :colspan="columns.length" class="hys-ui-empty"><slot name="empty">{{emptyText||'暂无数据'}}</slot></td></tr></template></tbody></table></div></template>
<style scoped>.hys-ui-table-striped tbody tr:nth-child(even){background:var(--hys-ui-surface-alt,var(--hys-ui-theme-surface-alt))}.hys-ui-table-bordered th,.hys-ui-table-bordered td{border:1px solid var(--hys-ui-border,var(--hys-ui-theme-border))}.hys-ui-table-sm :deep(td),.hys-ui-table-sm :deep(th){padding:7px 10px}.hys-ui-table-lg :deep(td),.hys-ui-table-lg :deep(th){padding:17px 18px}.hys-ui-table-sort{display:inline-flex;align-items:center;gap:6px;border:0;background:transparent;color:inherit;font:inherit;font-weight:inherit;padding:0}.hys-ui-data-table caption{text-align:left;padding:10px 14px;font-weight:600}</style>
